import sys
import os
import glob
import math
import importlib

# 1. Path configuration for the 'generated' directory
current_dir = os.path.dirname(os.path.abspath(__file__))
generated_dir = os.path.join(current_dir, 'generated')

# Add the 'generated' folder to the Python PATH for imports
sys.path.append(generated_dir)

# 2. Automated search for the latest file generated by T1
t1_files = glob.glob(os.path.join(generated_dir, 't1-result-*.py'))
if not t1_files:
    print("❌ Error: No 't1-result-*.py' file found in the 'generated/' directory.")
    sys.exit(1)

# Retrieve the most recent file
latest_t1_file = max(t1_files, key=os.path.getctime)
module_name = os.path.basename(latest_t1_file).replace('.py', '')

print(f"📄 T1 Model detected: {module_name}.py")

# Dynamic import of the object model
t1_module = importlib.import_module(module_name)
qubo_model = t1_module.object_model

def generate_t2_besser_instance(qubo_model, output_filepath):
    # 3. Extraction and strict alphabetical sorting for qubit ordering
    bin_vars = sorted([v for v in qubo_model.objects if v.classifier.name == "BinaryVariable"], key=lambda x: x.name)
    lin_terms = [t for t in qubo_model.objects if t.classifier.name == "LinearTerm"]
    quad_terms = [t for t in qubo_model.objects if t.classifier.name == "QuadraticTerm"]
    
    num_qubits = len(bin_vars)
    var_to_q = {v: i for i, v in enumerate(bin_vars)}
    
    # Static angles for QAOA (1 layer)
    gamma = math.pi / 8
    beta = math.pi / 4

    # 4. Initialization of the BESSER instance code
    code_lines = [
        "from besser.BUML.metamodel.quantum import (",
        "    QuantumCircuit, QuantumRegister, ClassicalRegister,",
        "    HadamardGate, PauliXGate, RZGate, RXGate, Measurement",
        ")",
        "",
        "qc = QuantumCircuit('Knapsack_QAOA')",
        f"q_reg = QuantumRegister('q', {num_qubits})",
        f"c_reg = ClassicalRegister('c', {num_qubits})",
        "qc.add_qreg(q_reg)",
        "qc.add_creg(c_reg)",
        ""
    ]

    code_lines.append("# Transformation Rule 1: Initial Superposition (Farhi et al., 2014)")
    for i in range(num_qubits):
        code_lines.append(f"qc.add_operation(HadamardGate(target_qubit={i}))")
        
    code_lines.append("\n# Transformation Rule 2: Linear terms mapped to Z-rotations (Lucas, 2014)")
    for lt in lin_terms:
        q_idx = var_to_q[lt.linearVariable]
        theta = 2 * gamma * lt.coefficient
        code_lines.append(f"qc.add_operation(RZGate(target_qubit={q_idx}, theta={theta}))")

    code_lines.append("\n# Transformation Rule 3: Quadratic terms mapped to ZZ-interactions (Nielsen & Chuang, 2010)")
    for qt in quad_terms:
        v_list = list(qt.variables)
        q1, q2 = var_to_q[v_list[0]], var_to_q[v_list[1]]
        theta = 2 * gamma * qt.coefficient
        code_lines.append(f"qc.add_operation(PauliXGate(target_qubit={q2}, control_qubits=[{q1}]))")
        code_lines.append(f"qc.add_operation(RZGate(target_qubit={q2}, theta={theta}))")
        code_lines.append(f"qc.add_operation(PauliXGate(target_qubit={q2}, control_qubits=[{q1}]))")

    code_lines.append("\n# Transformation Rule 4: Mixer Hamiltonian (Farhi et al., 2014)")
    for i in range(num_qubits):
        code_lines.append(f"qc.add_operation(RXGate(target_qubit={i}, theta={2 * beta}))")

    code_lines.append("\n# Transformation Rule 5: Measurements")
    for i in range(num_qubits):
        code_lines.append(f"qc.add_operation(Measurement(target_qubit={i}, output_bit={i}))")

    # 5. File generation directly in 'generated/'
    with open(output_filepath, "w", encoding="utf-8") as f:
        f.write("\n".join(code_lines))
    print(f"✅ Step T2 successful! File created: {output_filepath}")

if __name__ == "__main__":
    output_path = os.path.join(generated_dir, "quantum_instance.py")
    generate_t2_besser_instance(qubo_model, output_path)